// Resolve Google Drive folder names to IDs
const formData = $input.first().json;
const folderNames = formData['Google Drive Folders'];

// Handle different input types: array, string, or null/undefined
let folders = [];

if (Array.isArray(folderNames)) {
  // Input is already an array
  folders = folderNames.filter(name => name && typeof name === 'string' && name.trim().length > 0).map(name => name.trim());
} else if (typeof folderNames === 'string' && folderNames.trim()) {
  // Input is a comma-separated string
  folders = folderNames.split(',').map(name => name.trim()).filter(name => name.length > 0);
}

if (folders.length === 0) {
  // No specific folders - pass through original data
  return [{
    json: {
      ...formData,
      folder_ids: [],
      folder_query: '',
      needs_folder_resolution: false
    }
  }];
}

return [{
  json: {
    ...formData,
    folder_names: folders,
    needs_folder_resolution: true
  }
}];

// Build folder query from resolved IDs
const folderResults = $input.all();
const originalData = $('Parse Folder Names').first().json;

if (folderResults.length === 0) {
  console.log('⚠️ No folders found matching the specified names');
  return [{
    json: {
      ...originalData,
      folder_ids: [],
      folder_query: '',
      folder_warning: 'No folders found matching the specified names'
    }
  }];
}

// Extract folder IDs
const folderIds = folderResults.map(folder => folder.json.id);
const foundFolders = folderResults.map(folder => folder.json.name);

// Build the folder query part
const folderQuery = folderIds.length > 0 
  ? ` and (${folderIds.map(id => `'${id}' in parents`).join(' or ')})` 
  : '';

console.log(`📁 Found ${folderIds.length} folders: ${foundFolders.join(', ')}`);

return [{
  json: {
    ...originalData,
    folder_ids: folderIds,
    folder_query: folderQuery,
    found_folders: foundFolders
  }
}];

// Process all file types (test mode gets metadata, ingest mode gets actual data)
const items = $input.all();
const formData = $('Google Drive Configuration Form').first().json;
const isTestMode = formData['Execution Mode'] === 'test';

return items.map(item => {
  // Check if this item has an error from the download step (only in ingest mode)
  if (item.error && !isTestMode) {
    console.log(`❌ Download failed for file ${item.json?.name || 'Unknown'}: ${item.error.message}`);

    return {
      json: {
        file_id: item.json?.id || 'unknown',
        name: item.json?.name || 'Unknown File',
        mime_type: item.json?.mimeType || 'unknown',
        web_view_link: item.json?.webViewLink || '',
        content: null,
        file_data: null,
        source_type: 'error',
        title: `Drive: ${item.json?.name || 'Unknown File'} (Download Failed)`,
        processing_method: getProcessingMethod(item.json?.mimeType || 'unknown'),
        test_mode: isTestMode,
        error: {
          message: item.error.message,
          type: item.error.name || 'DownloadError',
          details: 'File download failed - check permissions'
        }
      }
    };
  }

  const { data, mimeType, name, id, webViewLink } = item.json;
  let content = null;
  let sourceType = 'upload';
  let processingMethod = getProcessingMethod(mimeType);

  function getProcessingMethod(mimeType) {
    const workspaceTypes = [
      'application/vnd.google-apps.document',
      'application/vnd.google-apps.presentation', 
      'application/vnd.google-apps.spreadsheet'
    ];
    return workspaceTypes.includes(mimeType) ? 'export' : 'download';
  }

  function getExportFormat(mimeType) {
    switch(mimeType) {
      case 'application/vnd.google-apps.document': return 'text/plain';
      case 'application/vnd.google-apps.presentation': return 'application/pdf';
      case 'application/vnd.google-apps.spreadsheet': return 'text/csv';
      default: return 'original format';
    }
  }

  if (isTestMode) {
    // Test mode: create mock content from metadata
    if (processingMethod === 'export') {
      content = `[TEST MODE - No actual content downloaded]\nFile: ${name}\nType: ${mimeType}\nLink: ${webViewLink}\n\nThis would be the exported content in ingest mode.\nFile would be converted to: ${getExportFormat(mimeType)}`;
      sourceType = 'text';
      processingMethod = 'export-test';
    } else if (mimeType === 'text/plain') {
      content = `[TEST MODE - No actual content downloaded]\nFile: ${name}\nType: ${mimeType}\nLink: ${webViewLink}\n\nThis would contain the actual text content in ingest mode.`;
      sourceType = 'text';
      processingMethod = 'download-test';
    } else {
      content = `[TEST MODE - Binary file not downloaded]\nFile: ${name}\nType: ${mimeType}\nSize: Would be determined after download\n\nThis file would be stored as binary data in ingest mode.`;
      sourceType = 'upload';
      processingMethod = 'download-test';
    }
  } else {
    // Ingest mode: process actual downloaded content
    if (processingMethod === 'export' && data) {
      // Google Workspace files are converted to text/plain, pdf, or csv
      if (typeof data === 'object' && data.type === 'Buffer') {
        content = Buffer.from(data.data).toString('utf-8');
      } else if (typeof data === 'string') {
        content = data;
      }
      sourceType = 'text';
    } else if (mimeType === 'text/plain' && data) {
      // Regular text files
      if (typeof data === 'object' && data.type === 'Buffer') {
        content = Buffer.from(data.data).toString('utf-8');
        sourceType = 'text';
      } else if (typeof data === 'string') {
        content = data;
        sourceType = 'text';
      }
    }
    // Other files remain as binary uploads (sourceType = 'upload')
  }

  console.log(`${isTestMode ? '🧪' : '✅'} Processed: ${name} (${mimeType}) - Mode: ${isTestMode ? 'test' : 'ingest'} - Method: ${processingMethod}`);

  return {
    json: {
      file_id: id,
      name: name,
      mime_type: mimeType,
      web_view_link: webViewLink,
      content: content,
      file_data: isTestMode ? null : data,
      source_type: sourceType,
      title: `Drive: ${name}`,
      processing_method: processingMethod,
      test_mode: isTestMode
    }
  };
});

// Enhanced Test mode - create summary with downloaded content preview
const items = $input.all();
const formData = $('Google Drive Configuration Form').first().json;
const mergeData = $('Merge Folder Resolution').first().json || {};

// Group files by processing method
const workspaceFiles = items.filter(item => item.json.processing_method === 'export-test' || item.json.processing_method === 'export');
const downloadedFiles = items.filter(item => item.json.processing_method === 'download-test' || item.json.processing_method === 'download');

// Create content previews
const contentPreviews = items.slice(0, 5).map(item => {
  const preview = {
    name: item.json.name,
    type: item.json.mime_type,
    id: item.json.file_id,
    link: item.json.web_view_link,
    processing_method: item.json.processing_method,
    source_type: item.json.source_type
  };

  // Add content preview if available
  if (item.json.content) {
    const content = item.json.content.toString();
    preview.content_preview = content.length > 200 ? 
      content.substring(0, 200) + '...' : content;
    preview.content_length = content.length;
  }

  return preview;
});

// Build folder information
const folderInfo = {
  folders_specified: formData['Google Drive Folders'] || '',
  folders_found: mergeData.found_folders || [],
  folder_search_applied: !!(mergeData.folder_query && mergeData.folder_query.trim()),
  folder_warning: mergeData.folder_warning || null
};

const summary = {
  success: true,
  mode: 'test',
  message: `✅ Google Drive test complete! Found and processed ${items.length} files${folderInfo.folder_search_applied ? ' from specified folders' : ' from all accessible folders'}`,
  files_found: items.length,
  files_processed: items.length,
  folder_info: folderInfo,
  processing_stats: {
    workspace_files_exported: workspaceFiles.length,
    other_files_downloaded: downloadedFiles.length,
    text_content_extracted: items.filter(i => i.json.content && i.json.content.length > 0).length,
    files_with_binary_data: items.filter(i => i.json.file_data && !i.json.content).length
  },
  content_previews: contentPreviews,
  configuration: {
    query_filter: formData['Google Drive Query Filter'],
    google_drive_folders: formData['Google Drive Folders'] || 'All folders',
    max_files: formData['Maximum Files'],
    api_url: formData['Open Notebook API URL'],
    embed_setting: formData['Embed Files for Search']
  },
  warnings: [
    'Test mode: Files downloaded and processed but NOT imported into notebook',
    items.length > 5 ? `Showing content preview for first 5 of ${items.length} files` : null,
    folderInfo.folder_warning
  ].filter(Boolean)
};

console.log('🧪 Enhanced Google Drive Test Results:', JSON.stringify(summary, null, 2));

return [{ json: summary }];

// Find Dense Summary transformation ID and prep source data
const transformations = $('Get Dense Summary Transformation').first().json;
const fileData = $('Process File Content').all();
let denseSummaryId = null;

if (Array.isArray(transformations)) {
  const denseSummary = transformations.find(t => t.name === 'Dense Summary');
  if (denseSummary) {
    denseSummaryId = denseSummary.id;
    console.log(`✅ Found Dense Summary transformation: ${denseSummaryId}`);
  } else {
    console.log('⚠️ Dense Summary transformation not found');
  }
} else {
  console.log('⚠️ Unable to fetch transformations');
}

// Pass through all file data with transformation ID
return fileData.map(item => ({
  json: {
    ...item.json,
    dense_summary_id: denseSummaryId
  }
}));

// Generate ingestion summary from all API results
const allItems = $input.all();
const successCount = allItems.filter(item => item.json.id).length;
const totalFiles = allItems.length;
const formData = $('Google Drive Configuration Form').first().json;
const mergeData = $('Merge Folder Resolution').first().json || {};

// Get file processing data for detailed results
const processingData = $('Add Transformation ID').all();

const results = allItems.map(item => {
  const matchingFile = processingData.find(f => 
    f.json.file_id === (item.json.metadata?.google_drive_id || item.json.google_drive_id)
  );

  return {
    name: matchingFile?.json.name || 'Unknown',
    source_id: item.json.id || null,
    success: !!item.json.id,
    processing_method: matchingFile?.json.processing_method || 'unknown',
    error: !item.json.id ? (item.json.error || 'Failed to create source') : null
  };
});

// Build folder information
const folderInfo = {
  folders_specified: formData['Google Drive Folders'] || '',
  folders_found: mergeData.found_folders || [],
  folder_search_applied: !!(mergeData.folder_query && mergeData.folder_query.trim()),
  folder_warning: mergeData.folder_warning || null
};

const summary = {
  success: successCount === totalFiles,
  mode: 'ingest',
  message: successCount === totalFiles ?
    `✅ Google Drive import complete! Successfully imported ${successCount} files${folderInfo.folder_search_applied ? ' from specified folders' : ' from all accessible folders'}` :
    `⚠️ Google Drive import completed with ${totalFiles - successCount} errors. ${successCount} files imported successfully.`,
  files_processed: totalFiles,
  sources_created: successCount,
  failed: totalFiles - successCount,
  folder_info: folderInfo,
  results: results,
  stats: {
    workspace_files: results.filter(r => r.processing_method === 'export').length,
    downloaded_files: results.filter(r => r.processing_method === 'download').length,
    text_sources: results.filter(r => r.processing_method === 'export').length,
    upload_sources: results.filter(r => r.processing_method === 'download').length
  },
  configuration: {
    query_filter: formData['Google Drive Query Filter'],
    google_drive_folders: formData['Google Drive Folders'] || 'All folders',
    max_files: formData['Maximum Files'],
    api_url: formData['Open Notebook API URL'],
    notebook_id: formData['Notebook ID'],
    embed_setting: formData['Embed Files for Search'],
    transformations_applied: !!processingData.find(f => f.json.dense_summary_id)
  },
  warnings: [
    totalFiles - successCount > 0 ? `${totalFiles - successCount} files failed to import - check API logs` : null,
    folderInfo.folder_warning
  ].filter(Boolean),
  errors: results.filter(r => r.error).map(r => ({
    file: r.name,
    error: r.error
  }))
};

console.log('📦 Google Drive Ingestion Summary:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
